import { apiFetch } from '../lib/api.js'

export type VaultAccess = 'read' | 'edit' | 'owner'

export interface Vault {
  id: string
  name: string
  ownerId: string
  mergeable: boolean
  access: VaultAccess
}

export function listVaults(): Promise<Vault[]> {
  return apiFetch('/vaults')
}

export function getVaultAccess(vaultId: string): Promise<{ access: VaultAccess }> {
  return apiFetch(`/vaults/${vaultId}/access`)
}

import { afterEach, describe, expect, it, vi } from 'vitest'
import { mockJsonResponse } from '../lib/api'
import { getVaultAccess, listVaults } from './vaults'

describe('vaults api', () => {
  afterEach(() => {
    vi.unstubAllGlobals()
  })

  it('listVaults calls GET /api/vaults', async () => {
    const fetchMock = vi.fn().mockResolvedValue(
      mockJsonResponse(200, [
        { id: 'v1', name: 'Engineering', ownerId: 'u1', mergeable: true, access: 'owner' },
      ]),
    )
    vi.stubGlobal('fetch', fetchMock)

    const vaults = await listVaults()

    expect(vaults).toEqual([
      { id: 'v1', name: 'Engineering', ownerId: 'u1', mergeable: true, access: 'owner' },
    ])
    expect(fetchMock).toHaveBeenCalledWith('/api/vaults', expect.objectContaining({ credentials: 'include' }))
  })

  it('getVaultAccess calls GET /api/vaults/:id/access', async () => {
    const fetchMock = vi.fn().mockResolvedValue(mockJsonResponse(200, { access: 'edit' }))
    vi.stubGlobal('fetch', fetchMock)

    const result = await getVaultAccess('v1')

    expect(result).toEqual({ access: 'edit' })
    expect(fetchMock).toHaveBeenCalledWith('/api/vaults/v1/access', expect.objectContaining({ credentials: 'include' }))
  })
})

import { useEffect, useRef } from 'react'
import { useOutletContext, useParams } from 'react-router'
import { useNote } from '../../hooks/useNote.js'
import { useUpdateNote } from '../../hooks/useUpdateNote.js'
import { useCodeMirrorEditor } from '../../hooks/useCodeMirrorEditor.js'
import type { Vault } from '../../api/vaults.js'

const SAVE_DEBOUNCE_MS = 1200

export function NoteView() {
  const { vaultId } = useParams<{ vaultId: string }>()
  const path = useParams()['*']
  const vault = useOutletContext<Vault | undefined>()
  const note = useNote(vaultId!, path!)

  if (note.isPending) return null
  if (note.isError) return <div className="p-8 text-muted-foreground">Note not found.</div>

  return (
    <NoteEditor
      // Remount key is the full note identity (vault + path), not just path:
      // if NoteView ever stays mounted across a cross-vault switch to the same
      // path (e.g. a future cross-vault wikilink), keying on path alone would
      // reuse the stale editor and PUT one vault's body into another's note.
      key={`${vaultId}/${path}`}
      vaultId={vaultId!}
      path={path!}
      vaultName={vault?.name}
      frontmatter={note.data!.frontmatter}
      initialBody={note.data!.body}
    />
  )
}

interface NoteEditorProps {
  vaultId: string
  path: string
  vaultName: string | undefined
  frontmatter: Record<string, unknown>
  initialBody: string
}

function NoteEditor({ vaultId, path, vaultName, frontmatter, initialBody }: NoteEditorProps) {
  const updateNote = useUpdateNote(vaultId, path)
  const timeoutRef = useRef<ReturnType<typeof setTimeout> | undefined>(undefined)

  useEffect(() => {
    return () => {
      if (timeoutRef.current) clearTimeout(timeoutRef.current)
    }
  }, [])

  function handleChange(newBody: string) {
    if (timeoutRef.current) clearTimeout(timeoutRef.current)
    timeoutRef.current = setTimeout(() => {
      updateNote.mutate({ body: newBody })
    }, SAVE_DEBOUNCE_MS)
  }

  const editorRef = useCodeMirrorEditor({ doc: initialBody, onChange: handleChange })

  return (
    <div className="flex h-full flex-col">
      <div className="border-b border-border px-8 py-4 text-sm text-muted-foreground">
        {vaultName ?? vaultId} / <span className="text-foreground">{path}</span>
      </div>
      <div className="border-b border-border px-8 py-4">
        <dl className="flex flex-col gap-1 text-sm">
          {Object.entries(frontmatter).map(([key, value]) => (
            <div key={key} className="flex gap-2">
              <dt className="font-medium text-muted-foreground">{key}:</dt>
              <dd>{typeof value === 'string' ? value : JSON.stringify(value)}</dd>
            </div>
          ))}
        </dl>
      </div>
      <div ref={editorRef} className="flex-1 overflow-auto" />
    </div>
  )
}

import { afterEach, describe, expect, it, vi } from 'vitest'
import { QueryClient, QueryClientProvider } from '@tanstack/react-query'
import { render, screen, waitFor } from '@testing-library/react'
import { createMemoryRouter, RouterProvider } from 'react-router'
import { mockJsonResponse } from '../../lib/api'
import { NoteView } from './NoteView'

function renderNote(initialPath: string) {
  const queryClient = new QueryClient({ defaultOptions: { queries: { retry: false } } })
  const router = createMemoryRouter(
    [{ path: '/vaults/:vaultId/notes/*', element: <NoteView /> }],
    { initialEntries: [initialPath] },
  )
  render(
    <QueryClientProvider client={queryClient}>
      <RouterProvider router={router} />
    </QueryClientProvider>,
  )
}

describe('NoteView', () => {
  afterEach(() => {
    vi.unstubAllGlobals()
    vi.useRealTimers()
  })

  it('renders the frontmatter and an editable CodeMirror body', async () => {
    vi.stubGlobal(
      'fetch',
      vi.fn().mockResolvedValue(
        mockJsonResponse(200, {
          path: 'people/jane',
          frontmatter: { type: 'people', timestamp: '2026-01-01T00:00:00.000Z' },
          body: '# Jane\n\nNotes about Jane.',
          updatedAt: '2026-01-01',
        }),
      ),
    )

    renderNote('/vaults/v1/notes/people/jane')

    await waitFor(() => expect(screen.getByText('type:')).toBeInTheDocument())
    const content = document.querySelector('.cm-content')
    expect(content).not.toBeNull()
    // CodeMirror renders each source line as its own .cm-line, so the body
    // text is split across children — assert both non-empty lines are present
    // rather than exact-matching a whitespace-collapsed textContent.
    expect(content!.textContent).toContain('# Jane')
    expect(content!.textContent).toContain('Notes about Jane.')
  })

  it('debounce-saves an edit to PUT /api/vaults/:id/notes/:path', async () => {
    vi.useFakeTimers({ shouldAdvanceTime: true })
    const fetchMock = vi.fn().mockImplementation((url: string, init?: RequestInit) => {
      if (init?.method === 'PUT') return Promise.resolve(mockJsonResponse(200, { id: 'n1', path: 'people/jane', frontmatter: {}, body: 'edited', updatedAt: '2026-01-02' }))
      return Promise.resolve(
        mockJsonResponse(200, { path: 'people/jane', frontmatter: {}, body: 'original', updatedAt: '2026-01-01' }),
      )
    })
    vi.stubGlobal('fetch', fetchMock)

    renderNote('/vaults/v1/notes/people/jane')
    await waitFor(() => expect(document.querySelector('.cm-content')).not.toBeNull())

    const { EditorView } = await import('@codemirror/view')
    const contentEl = document.querySelector('.cm-editor') as HTMLElement
    const view = EditorView.findFromDOM(contentEl)!
    view.dispatch({ changes: { from: 0, to: view.state.doc.length, insert: 'edited' } })

    const putCalls = () =>
      fetchMock.mock.calls.filter(([, init]) => (init as RequestInit | undefined)?.method === 'PUT')

    // Still inside the ~1200ms debounce window — the save must NOT have fired
    // yet. (This assertion is what gives the test teeth: it fails if the
    // debounce is removed and the PUT fires immediately.)
    await vi.advanceTimersByTimeAsync(800)
    expect(putCalls()).toHaveLength(0)

    // Past the window — the debounced save fires exactly once, with the edit.
    await vi.advanceTimersByTimeAsync(700)
    await waitFor(() => expect(putCalls()).toHaveLength(1))
    expect(fetchMock).toHaveBeenCalledWith(
      '/api/vaults/v1/notes/people/jane',
      expect.objectContaining({ method: 'PUT', body: JSON.stringify({ body: 'edited' }) }),
    )
  })

  it('shows a not-found message for a missing note', async () => {
    vi.stubGlobal('fetch', vi.fn().mockResolvedValue(mockJsonResponse(404, { error: 'note not found' })))

    renderNote('/vaults/v1/notes/people/ghost')

    await waitFor(() => expect(screen.getByText('Note not found.')).toBeInTheDocument())
  })
})

import { useEffect, useRef } from 'react'
import { EditorState } from '@codemirror/state'
import { EditorView, keymap } from '@codemirror/view'
import { defaultKeymap, history, historyKeymap } from '@codemirror/commands'
import { markdown } from '@codemirror/lang-markdown'

interface UseCodeMirrorEditorOptions {
  doc: string
  onChange: (doc: string) => void
  readOnly?: boolean
}

export function useCodeMirrorEditor({ doc, onChange, readOnly = false }: UseCodeMirrorEditorOptions) {
  const containerRef = useRef<HTMLDivElement>(null)
  const onChangeRef = useRef(onChange)
  // Keep the ref pointing at the latest onChange without re-running the
  // mount effect below. Assigned in an effect (not during render) so the
  // update is a committed side effect — the CM6 updateListener only reads
  // this ref at edit time, always after this effect has run.
  useEffect(() => {
    onChangeRef.current = onChange
  })

  useEffect(() => {
    if (!containerRef.current) return

    const state = EditorState.create({
      doc,
      extensions: [
        history(),
        keymap.of([...defaultKeymap, ...historyKeymap]),
        markdown(),
        EditorView.updateListener.of((update) => {
          if (update.docChanged) onChangeRef.current(update.state.doc.toString())
        }),
        EditorView.theme({
          '&': { fontFamily: 'var(--font-mono)', fontSize: '14px', height: '100%' },
          '.cm-content': { fontFamily: 'var(--font-mono)' },
          '.cm-scroller': { overflow: 'auto' },
        }),
        // A genuinely non-editable rendered view needs BOTH: readOnly blocks
        // edit transactions/commands, editable=false drops contentEditable so
        // there's no caret. (CM6's documented recipe for a true read-only view.)
        ...(readOnly ? [EditorState.readOnly.of(true), EditorView.editable.of(false)] : []),
      ],
    })

    const view = new EditorView({ state, parent: containerRef.current })

    return () => {
      view.destroy()
    }
    // Mount once per component instance — `doc` and `readOnly` are captured at
    // mount. Callers that need a different `readOnly` remount this component
    // (Task 2 keys on it), matching how `doc` is already handled.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [])

  return containerRef
}

